package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import static it.frociart.app.FlowModel.*;
public final class PauseImportTests {
 static int checks;static void check(boolean yes,String why){if(!yes)throw new AssertionError(why);checks++;}static String text(String s){return FlowEngine.evaluate(s,Collections.emptyMap()).format();}static String normal(String s){return s.replace("\r\n","\n");}static List<Node> nodes(Document d){List<Node> n=new ArrayList<>(d.nodes);if(d.functions!=null)for(Function f:d.functions)n.addAll(f.body.nodes);return n;}
 static void run(Document d,String[] row,boolean ignore){String before=FlowCodec.encode(d);FlowEngine.Runner r=new FlowEngine.Runner(d);FlowDebugger debug=new FlowDebugger(r,d);debug.ignoreBreakpoints=ignore;List<String> hits=new ArrayList<>();debug.begin(FlowDebugger.Command.CONTINUE);for(int i=0;i<3000&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++){int steps=r.steps;String id=r.currentNodeId;debug.tick();if(!debug.active()&&debug.atBreakpoint()){check(r.steps==steps&&r.currentNodeId.equals(id),"Pause before execution");hits.add(r.variables.containsKey("x")?r.variables.get("x").format():"_");check(debug.begin(FlowDebugger.Command.CONTINUE),"Resume accepted");}}check(r.state==FlowEngine.State.COMPLETED,"Completes "+row[0]+": "+r.errorMessage);check(normal(r.outputText()).equals(text(row[1])),"Exact output "+row[0]);check(String.join("|",hits).equals(ignore?"":row[2]),"Exact pause order "+row[0]+": "+String.join("|",hits));check(FlowCodec.encode(d).equals(before),"Debug does not edit graph");}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);Files.createDirectories(root.resolve("android"));for(String line:Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.UTF_8)){String[] row=line.split("\t",-1);Path path=root.resolve("fixtures/"+row[0]+".fprg");byte[] before=Files.readAllBytes(path);Document d=FlowgorithmImport.decode(new String(before,StandardCharsets.UTF_8));long count=nodes(d).stream().filter(n->n.kind==PAUSE).count();check(count>0&&nodes(d).stream().filter(n->n.kind==PAUSE).allMatch(n->n.text.equals("Pausa")&&n.breakpoint),"Dedicated nodes, no fake assignments");check(!FlowCodec.encode(d).contains("PRIVATE_"),"Metadata removed");run(d,row,false);run(d,row,true);run(d.copy(),row,false);Document pseudo=FlowPseudocode.decode(FlowPseudocode.encode(d));check(nodes(pseudo).stream().filter(n->n.kind==PAUSE).count()==count,"Pseudocode keeps every pause");run(pseudo,row,false);Path save=root.resolve("android/"+row[0]+".frociart");Files.write(save,FlowCodec.encode(d).getBytes(StandardCharsets.UTF_8));run(FlowCodec.decode(new String(Files.readAllBytes(save),StandardCharsets.UTF_8)),row,false);FlowAutoLayout.apply(d);run(d,row,false);check(Arrays.equals(before,Files.readAllBytes(path)),"Source unchanged");String python=new String(Files.readAllBytes(root.resolve("../frociart-v1-capabilities/android/app/src/main/assets/PythonRuntime.py")),StandardCharsets.UTF_8),java=new String(Files.readAllBytes(root.resolve("../frociart-v1-capabilities/android/app/src/main/assets/JavaRuntime.txt")),StandardCharsets.UTF_8);Path generated=root.resolve("generated-android");Files.createDirectories(generated);String className="Android"+Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.UTF_8).indexOf(line);Files.write(generated.resolve(className+".java"),FlowJava.generate(FlowSource.compile(d),java,className).text.getBytes(StandardCharsets.UTF_8));Files.write(generated.resolve(row[0]+".py"),FlowPython.generate(FlowSource.compile(d),python).text.getBytes(StandardCharsets.UTF_8));check(true,"Both source exporters accept pause");}
 try(java.util.stream.Stream<Path> files=Files.list(root.resolve("fixtures"))){for(Path f:(Iterable<Path>)files.filter(p->p.getFileName().toString().startsWith("reject-"))::iterator){boolean rejected=false;try{FlowgorithmImport.decode(new String(Files.readAllBytes(f),StandardCharsets.UTF_8));}catch(IllegalArgumentException e){rejected=e.getMessage().contains("Flowgorithm");}check(rejected,"Atomic reject "+f.getFileName());}}
 for(String code:new String[]{"PAUSA","PAUSA SE x >= 3","PAUSA_DISATTIVATA","PAUSA_DISATTIVATA SE x >= 3","PAUSA_DISATTIVATA SE x >"}){Document d=FlowPseudocode.decode("x = 3\n"+code+"\nSTAMPA x");String[] row={code,"\"3\"",code.startsWith("PAUSA_DISATTIVATA")?"":"3"};run(d,row,false);run(FlowPseudocode.decode(FlowPseudocode.encode(d)),row,false);}
 Document d=FlowPseudocode.decode("x = 5\nPAUSA SE 42\nSTAMPA x");FlowEngine.Runner r=new FlowEngine.Runner(d);FlowDebugger c=new FlowDebugger(r,d);c.begin(FlowDebugger.Command.CONTINUE);for(int i=0;i<20&&c.active();i++)c.tick();check(c.atBreakpoint()&&c.message().contains("vero o falso")&&r.output.isEmpty(),"Bad condition type pauses before side effects");c.begin(FlowDebugger.Command.CONTINUE);for(int i=0;i<20&&c.active();i++)c.tick();check(r.state==FlowEngine.State.COMPLETED&&r.outputText().equals("5"),"Resume after condition error");System.out.println("PAUSE_IMPORT_ANDROID PASS checks="+checks);
 }
}
